-- German for story/story_*.lua; a missing key shows the English.

local T = {}

T["You find yourself walking through the quaint Fox Village in the forest."] = "Du spazierst gerade durch das malerische Fuchsdorf im Wald."
T["It's a cloudy day, painting the town in a tone of gray."] = "Es ist ein bewölkter Tag, der das Dorf in graue Töne taucht."
T["Suddenly, you hear footsteps coming your way, and an impact against you blows you to the ground!"] = "Plötzlich hörst du Schritte näher kommen -- und ein heftiger Zusammenprall wirft dich zu Boden!"
T["You open your eyes back up, and find a familiar looking young fox boy crying."] = "Du öffnest die Augen wieder. Vor dir sitzt ein weinender Fuchsjunge, der dir irgendwie bekannt vorkommt."
T["Are you okay? What's wrong?"] = "Alles okay? Was ist los?"
T["Ow..."] = "Autsch …"
T["HEY! I'M WALKING HERE!"] = "EY! AUGEN AUF, ICH LAUF HIER!"
T["Ah, I'm so sorry! I..."] = "Ah, das tut mir so leid! Ich …"
T["The boy pauses for a second, looking at you carefully."] = "Der Junge hält kurz inne und mustert dich genau."
T["You... {pause:0.4}\nYou're the one that's been visiting our dojo lately..."] = "Du … {pause:0.4}\nDu kommst doch in letzter Zeit öfter in unser Dojo …"
T["Ume?"] = "Ume?"
T["You're... Tsutaki! Right?"] = "Du bist … Tsutaki! Stimmt’s?"
T["Who's this brat"] = "Wer ist denn dieser Rotzlöffel"
T["Phew... I'm glad to run into someone I already know..."] = "Puh … Ich bin froh, dass ich jemandem begegne, den ich schon kenne …"
T["The boy makes a disappointed expression."] = "Der Junge macht ein enttäuschtes Gesicht."
T["I... {pause:0.4}\nI suppose I never introduced myself properly."] = "Ich … {pause:0.4}\nIch hab mich wohl nie richtig vorgestellt."
T["I'm Ume... {pause:0.4}\nI've seen you at our dojo, playing taiko drums before..."] = "Ich bin Ume … {pause:0.4}\nIch hab dich schon mal in unserem Dojo Taiko spielen sehen …"
T["Good to see you, but what's the matter?"] = "Schön, dich zu sehen, aber was ist los?"
T["How come?"] = "Wieso denn?"
T["That's a weird way to say \"nice to see you.\""] = "Was für ein „Schön, dich zu sehen“."
T["{shake:14,0.35}{sfx:shock}I'm sorry... {pause:0.4}\nI don't mean to be rude... {pause:0.4}\nBut..."] = "{shake:14,0.35}{sfx:shock}Tut mir leid … {pause:0.4}\nIch will nicht unhöflich sein … {pause:0.4}\nAber …"
T["Ume seems pretty scared, so you pause to listen to what he has to say."] = "Ume wirkt ziemlich verängstigt, also hältst du inne und hörst ihm zu."
T["Well, you see... {pause:0.4}\nThere's this quiet pagoda holding our ancestors relics deep in the woods and... {pause:0.4}\nRecently, the aura around it turned all... weird, and stuff."] = "Also, weißt du … {pause:0.4}\nTief im Wald steht eine stille Pagode mit den Reliquien unserer Ahnen, und … {pause:0.4}\nIn letzter Zeit ist die Aura um sie herum ganz … komisch geworden und so."
T["It's normally empty and serene, but it started to have a strange dark energy enveloping it, more and more with each day I visit."] = "Normalerweise ist es dort leer und friedlich, aber jetzt umhüllt sie eine seltsame dunkle Energie -- und jedes Mal, wenn ich hingehe, wird sie stärker."
T["The stream around it has become as big as a lake, growing just like the weird darky stuff..."] = "Der Bach drumherum ist so groß wie ein See geworden und wächst genauso wie das komische Dunkelzeug …"
T["And... when I stepped inside, even just one step... {pause:0.4}\nsome... {pause:0.4}{expr:fear2}some creature tried to attack me! {pause:0.4}\nIt was scary... I'm scared...!!"] = "Und … als ich reingegangen bin, nur einen einzigen Schritt … {pause:0.4}\nhat so ein … {pause:0.4}{expr:fear2}so ein Wesen versucht, mich anzugreifen! {pause:0.4}\nDas war so gruselig … Ich hab Angst …!!"
T["Have you asked one of your grown-ups about it?"] = "Hast du schon einen Erwachsenen gefragt?"
T["That's called a squirrel. It's just a squirrel."] = "Das ist ein Eichhörnchen, nichts weiter."
T["Well... Tsubaki thinks I'm lying, or that it's not important. {pause:0.4}\nShe says it's so deep in the woods that it wouldn't matter, but it's CLEARLY dangerous! {pause:0.4}\nSUPER DUPER dangerous!"] = "Na ja … Tsubaki glaubt, dass ich lüge oder dass es nicht wichtig ist. {pause:0.4}\nSie sagt, das ist so tief im Wald, dass es egal ist, aber es ist EINDEUTIG gefährlich! {pause:0.4}\nSUPERMEGA gefährlich!"
T["Asagao didn't say anything or do anything about it, so maybe they think I'm making it up too, but..."] = "Asagao hat nichts dazu gesagt und auch nichts unternommen, also glaubt Asagao wohl auch, dass ich mir das ausdenke, aber …"
T["I feel like if we don't do something soon, our village could be in some really bad danger..."] = "Ich hab das Gefühl, wenn wir nicht bald was unternehmen, gerät unser Dorf in ganz schlimme Gefahr …"
T["... Do you think you could help me, maybe? {pause:0.4}\nYou're the only other super strong person I can think of..."] = "… Meinst du, du könntest mir vielleicht helfen? {pause:0.4}\nDu bist die einzige andere superstarke Person, die mir einfällt …"
T["Of course, Ume. Take me there."] = "Natürlich, Ume. Bring mich hin."
T["Ume looks down, with an upset expression. {pause:0.4}\nHe took that in a not-great way."] = "Ume senkt den Blick, sichtlich gekränkt. {pause:0.4}\nDas kam wohl nicht so gut an."
T["{shake:14,0.35}{sfx:shock}It... {pause:0.4}It wasn't a squirrel... {pause:0.4}I promise..."] = "{shake:14,0.35}{sfx:shock}Das … {pause:0.4}Das war kein Eichhörnchen … {pause:0.4}Ehrlich …"
T["I really need your help... {pause:0.4}\nNo one else believes me either, but it really could put the village in some bad danger..."] = "Ich brauche wirklich deine Hilfe … {pause:0.4}\nSonst glaubt mir auch keiner, aber das könnte das Dorf echt in große Gefahr bringen …"
T["Can I at least show you the scary thing...? {pause:0.4}\nYou're really my last hope..."] = "Darf ich dir wenigstens das gruselige Ding zeigen …? {pause:0.4}\nDu bist echt meine letzte Hoffnung …"
T["I'm sorry, I didn't mean to hurt your feelings. Show me, I'll help."] = "Sorry, ich wollte dich nicht kränken. Zeig’s mir, ich helfe dir."
T["... Uh, okay..."] = "… Äh, okay …"
T["The squirrel? Yeah, I guess."] = "Das Eichhörnchen? Na gut."
T["No."] = "Nein."
T["It's not a squirrel!!"] = "Es ist kein Eichhörnchen!!"
T["The two of you reach the forest from the dojo backdoor, and are ready for a long journey."] = "Ihr beide gelangt durch die Hintertür des Dojos in den Wald, bereit für eine lange Reise."
T["The two of you run through the forest, and reach the entrance gate to the sacred place.\nA long climb waits before reaching the deserted pagoda."] = "Ihr beide lauft durch den Wald und erreicht das Eingangstor zur heiligen Stätte.\nBis zur verlassenen Pagode liegt ein langer Aufstieg vor euch."
T["The two of you run through the forest, and reach the deserted pagoda, which was indeed distorted with purple hues.\nYou feel like something bad is brewing inside."] = "Ihr beide lauft durch den Wald und erreicht die verlassene Pagode, die tatsächlich von violetten Schlieren verzerrt ist.\nDu spürst, dass sich darin etwas Böses zusammenbraut."
T["The two of you enter the pagoda."] = "Ihr beide betretet die Pagode."
T["Wait! Pleas-"] = "Warte! Bitt--"
T["You leave the fox village, leaving it to its terrible fate...\nYou're hungry, stopping by the local convenience store before going back home."] = "Du verlässt das Fuchsdorf und überlässt es seinem schrecklichen Schicksal …\nDu hast Hunger und schaust noch kurz beim Kiosk um die Ecke vorbei, bevor du nach Hause gehst."
T["Hey Boss! {pause:0.4}\nAre you ready to take on the pagoda again?"] = "Hey, Boss! {pause:0.4}\nBist du bereit, es wieder mit der Pagode aufzunehmen?"
T["Sure am!"] = "Na klar!"
T["Boss???"] = "Boss???"
T["Pago... Pagowhat?"] = "Pago … Pagowas?"
T["I literally don't want to, tiny coward"] = "Hab echt null Bock, du kleiner Schisser"
T["Thank you! {pause:0.4}\nI'm happy to hear that!"] = "Danke! {pause:0.4}\nDas freut mich zu hören!"
T["You're the bigger, stronger person! {pause:0.4}\nThat's what a boss is, right? {pause:0.4}\n...Right?"] = "Du bist größer und stärker als ich! {pause:0.4}\nGenau das macht doch einen Boss aus, oder? {pause:0.4}\n… Oder?"
T["I suppose so."] = "Schätze schon."
T["I'm not sure that's how it works..."] = "Ich glaub nicht, dass das so läuft …"
T["Yes, my minion."] = "Ja, mein Lakai."
T["Minion...?? {pause:0.4}\n... *Ahem.*"] = "Lakai …?? {pause:0.4}\n… *Räusper.*"
T["Ume blinks at you, concerned."] = "Ume blinzelt dich besorgt an."
T["Uh... {pause:0.4}Y'know... {pause:0.4}\nthe... {pause:0.4}the thing... {pause:0.4}\nthe thing we did..."] = "Äh … {pause:0.4}Na, du weißt schon … {pause:0.4}\ndas … {pause:0.4}das Ding … {pause:0.4}\ndas Ding, das wir gemacht haben …"
T["... {pause:0.4}\nUgh... {pause:0.4}\nokay..."] = "… {pause:0.4}\nOh Mann … {pause:0.4}\nokay …"
T["Ume sighs, and explains it all to you again."] = "Ume seufzt und erklärt dir alles noch einmal."
T["You start walking away from Ume."] = "Du drehst dich um und gehst einfach von Ume weg."
T["{shake:14,0.35}{sfx:shock}NOO WAIT!! {pause:0.4}WAAIT!!!"] = "{shake:14,0.35}{sfx:shock}NEEIN, WARTE!! {pause:0.4}WAAARTE!!!"
T["Ume drags you back, before trying to convince you to help."] = "Ume zerrt dich zurück und versucht, dich zum Helfen zu überreden."
T["Remember, any progress is good progress. {pause:0.4}\nAs long as we get in there and give them even a smidge of a scare, I think the village would be safe, but..."] = "Denk dran: Jeder Fortschritt ist ein guter Fortschritt. {pause:0.4}\nSolange wir da reingehen und ihnen wenigstens ein kleines bisschen Angst einjagen, ist das Dorf, glaub ich, sicher, aber …"
T["I don't want the pagoda to stay like this forever... {pause:0.4}\nI'm sure, someday, we'll make it to the very top and restore it!"] = "Ich will nicht, dass die Pagode für immer so bleibt … {pause:0.4}\nIch bin sicher, eines Tages schaffen wir es bis ganz nach oben und bringen sie wieder in Ordnung!"
T["That's the spirit, Ume!"] = "So gefällt mir das, Ume!"
T["That's optimistic."] = "Ganz schön optimistisch."
T["I don't want to play with you anymore."] = "Ich will nicht mehr mit dir spielen."
T["...bye HAHAHAAHAAAHA"] = "… tschüss HAHAHAAHAAAHA"
T["You leave the fox village, leaving it to its terrible fate..."] = "Du verlässt das Fuchsdorf und überlässt es seinem schrecklichen Schicksal …"
T["You're hungry, stopping by the local convenience store before going back home."] = "Du hast Hunger und schaust noch kurz beim Kiosk um die Ecke vorbei, bevor du nach Hause gehst."
T["The two of you enter the forest behind the dojo."] = "Ihr beide betretet den Wald hinter dem Dojo."
T["The two of you reach the stairs leading to the pagoda."] = "Ihr beide erreicht die Treppe, die zur Pagode hinaufführt."
T["The once-deserted pagoda, now reaching to the edge of the sky shines in the middle of the forest, glowing in sunlight."] = "Die einst verlassene Pagode, die nun bis an den Rand des Himmels reicht, erstrahlt mitten im Wald im Sonnenlicht."
T["Heeeey, Boss!!!!!"] = "Heeeey, Boss!!!!!"
T["Ume is energetically running towards you."] = "Ume kommt voller Energie auf dich zugerannt."
T["I'm so happy to run into you here!"] = "Ich freu mich so, dich hier zu treffen!"
T["I am too!"] = "Ich mich auch!"
T["Ok bud."] = "Jaja, Kleiner."
T["The two of you stand there, taking in the scenery of nature."] = "Ihr beide steht da und genießt die Natur um euch herum."
T["The two of you stand there, taking in the scenery of nature. {pause:0.4}\nHe didn't understand that you were trying to dismiss him."] = "Ihr beide steht da und genießt die Natur um euch herum. {pause:0.4}\nEr hat nicht kapiert, dass du ihn abwimmeln wolltest."
T["It's still so strange isn't it? {pause:0.4}\nI wonder why Tobiraph did everything that it did."] = "Irgendwie ist das alles immer noch so seltsam, oder? {pause:0.4}\nIch frag mich, warum Tobiraph das alles getan hat."
T["I've been thinking about it too. I sorta want to know more."] = "Hab auch drüber nachgedacht. Ich wüsste gern mehr."
T["..."] = "…"
T["Hey, why don't we play pretend that it's still.. weird? {pause:0.4}\nI had so much fun with you, and I kind of wish we could do it again."] = "Hey, wollen wir nicht so tun, als wär alles noch … komisch? {pause:0.4}\nEs hat so viel Spaß mit dir gemacht, und irgendwie wünsch ich mir, wir könnten das noch mal machen."
T["I'd be happy to!"] = "Sehr gerne!"
T["That's why I'm here."] = "Deshalb bin ich ja hier."
T["You nod."] = "Du nickst."
T["Maybe another time."] = "Vielleicht ein andermal."
T["Understood! Don't hesitate to come anytime..."] = "Verstanden! Komm einfach vorbei, wann immer du willst …"
T["You leave the fox village...\nWhy did you came here already?"] = "Du verlässt das Fuchsdorf …\nWarum warst du noch mal hergekommen?"
T["The two of you enter the forest behind the dojo, with eyes filled with imagination."] = "Ihr beide betretet den Wald hinter dem Dojo, die Augen voller Fantasie."
T["The two of you reach the stairs leading to the pagoda, with eyes filled with imagination."] = "Ihr beide erreicht die Treppe zur Pagode, die Augen voller Fantasie."
T["The two of you enter the pagoda, with eyes filled with imagination."] = "Ihr beide betretet die Pagode, die Augen voller Fantasie."
T["... {pause:0.4}\nThat look on your face is telling me that you want to climb higher."] = "… {pause:0.4}\nDein Blick verrät mir, dass du noch höher hinaufwillst."
T["I am!"] = "Und wie!"
T["I just wanna check it out."] = "Ich will mich nur mal umsehen."
T["Neva neva neva!"] = "Nö, nö und nochmals nö!"
T["Then I'll go up to the roof with you, too!"] = "Dann komm ich mit dir bis aufs Dach!"
T["... {pause:0.4}\nThough I probably won't climb that thing, there's some stuff I need to check on inside the pagoda."] = "… {pause:0.4}\nAuf das Ding da klettere ich aber wohl nicht. Ich muss in der Pagode noch nach ein paar Sachen sehen."
T["I'll cheer you on the best I can, though!"] = "Aber ich feuere dich an, so gut ich kann!"
T["You start climbing the beanstalk, without knowing what to expect..."] = "Du beginnst, die Bohnenranke hinaufzuklettern, ohne zu wissen, was dich erwartet …"

return T
